import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易经传集解卷十七","description":"周易经传集解 - 周易经传集解卷十七","frontmatter":{"title":"周易经传集解卷十七","description":"周易经传集解 - 周易经传集解卷十七"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/018.md","filePath":"zh/classics/jingchuan-jijie/018.md"}'),r={name:"zh/classics/jingchuan-jijie/018.md"};function c(o,a,l,d,p,h){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易经传集解卷十七",tabindex:"-1"},[n("周易经传集解卷十七 "),e("a",{class:"header-anchor",href:"#周易经传集解卷十七","aria-label":"Permalink to “周易经传集解卷十七”"},"​")],-1),e("p",null,"钦定四库全书周易经传集解遁大壮卷十七 ​宋林栗撰序卦曰：恒者，久也。物不可以久居其所，故受之以「遁」。「遁」之成卦，恒之变也。自「恒」之「遁」，二、五相易，变其上爻而成「遁」也。二、五相易，则乾巽不交矣。变其上爻，则阳刚居外矣。夫乾以三阳而降于三阴之中，虽刚柔上下，进退无常，然皆内阳而外阴，内健而外顺，是以为「咸」、为「恒」也。今二、五变而不交，上九出而居外，则是内阴而外阳，内柔而外刚矣，是以谓之「遁」也。「遁」之言退也，二阴浸长，得位居内，四阳虽盛，失势居外，小人进而君子退也。主君子而言，是故以「遁」名之。君子也者，知进退存亡而不失其正，消息盈虚，与时偕行者也。四阳见二阴之长，遁而去之，所以全其刚也。或曰：三阴长而为「否」，五阴极而为「剥」，君子犹居其间。二阴方长，四阳未衰，曷为「遁」哉？曰：「否」阴三，故自四以往，君子居之；剥阴穷于五，故上九一爻，君子居之。遁阴方长，未可与争君子，是以见几而作也。今夫泰交之世，非尽灭小人而独生君子也，小人变而为君子也。否剥之世，非尽灭君子而独生小人也，君子化而为小人也。故一阴之生，则曰「不可与长也」；二阴之生，则曰「浸而长也」。若三阴之长，则君子之党半为小人，其道消矣。故夫知几之君子，见二阴之浸长，惧为所消，是以遁而去之也。苟晏安酖毒，怀禄不去，则日朘月削，陷于柔邪而不自知矣。二阴而遁，不亦宜乎？遁：亨，小利贞。彖曰：「遁亨」，遁而亨也。刚当位而应，与时行也。「小利贞」，浸而长也。遁之时义大矣哉！下艮上乾。成卦曰「遁」者，初为艮，二为巽，三四为乾。乾，阳也，艮亦阳也。同类相从，固其所也，又何遁哉？乾，健也；艮，止也。下止而应，上健而行，斯其志矣，又何遁哉？为其有巽之象焉。巽为入为伏，而在下卦之中，乾之所为「遁」也。彼以柔巽之道，既入而伏其中矣，而乃以高爵重禄啖我以利，甘辞媚色，阳为深交。君子于此，可不遁而去之乎？何者？其措心积虑，惟欲吾道之消也。「遁亨」何谓也？曰：遁非可亨之时，能遁而后亨也。于斯之时，苟不知遁，则君子之道日消而尽，何自亨哉？「否」之六二亦曰「大人否」，否则不亨也。夫以九五当位，而有六二为之应，然而遁者何也？消息盈虚，与时偕行也。君子履霜而知坚冰之渐，可以牵于系应而不自为去就也哉？故曰「尺蠖之屈，以求伸也；龙蛇之蛰，以存身也；君子之遁，以求亨也」。「小利贞」何谓也？曰：阳为大，阴为小。方遁之时，二阴浸长而皆有其应。六二居中，而巽以承上，以此为贞，小人之利也。夫所恶于二阳者，为其浸长而不可遏也。苟贞于此，则小人在下，而君子在上，何不利之有哉？是故泰之二、五，则「利君子贞」，否之二、五，则「不利君子贞」。「遁」之二、五，犹「小利贞」，不可以大有为也。夫九五、六二三卦不殊，则君子、小人之贞有利不利焉，可不深求其故哉？故子曰：「遁亨，遁而亨也。刚当位而应，与时行也。小利贞，浸而长也。遁之时义大矣哉！」苏氏曰：遁非避患之遁，以为非遁无以反乎其君之心也。今二阴在内，而其势至锐，而其朋至寡。锐则其终必至于胜，寡则其心常欲得众。圣人畏其有必胜之渐，而知其乖众之意，是以使阳遁阴。阳皆遁，则阴无与处，而思求阳，阴思求阳，而后阳可以处，此遁之所由亨也。苏氏此论，是非相杂，近于押阖要君者之所为。惧学者之易流，不可以训，故为正之。夫二阴方锐，其党未强，而其势必胜。与之争，则吾道必消，不争亦必消。惟遁而去之，则可以全刚也。非独可以全吾之刚，亦足以悟君之感也。四阳既遁，阴无能为，危莫与持，颠莫与扶，则将反之而为「大壮」矣。故圣人作易，以「壮」继「遁」。盖言二阴之世，君子能遁，则「大壮」有反掌之易。惟其怀禄不能遁去，则日消而为阴，阴遂强盛而不可救耳。苟已遁而君犹不悟，则如之何？曰：遁而不悟，则「否」之象见矣。险德避难，斯亦可矣，又何求哉？故齐归女乐三日，而夫子出走，犹曰「迟迟吾行」，盖有所待焉尔。孟轲三宿出昼，而齐王不追，然后浩然有归志也。而苏氏以为非避患之遁，是岂要君之遁乎？又谓「阴思求阳，则阳可以处」。夫阴之用事，未尝不思求阳也。求而与之者，是为其所消也。故「遁」之九四、九五，皆有正应，与之嘉好，脱身而去，莫之肯留者，畏其消也。苟曰「阴思求阳，则阳可以处」，如是则小人为主，君子为客，遁何自亨哉？由遁而为大壮，亨之义也。王叔文用事，以杜佑故相，名高位重，使领度支，而己为之副。君子观此之象，可以不遁乎哉？贾耽、郑珣瑜去之晚矣。象曰：天下有山，「遁」。君子以远小人，不恶而严。天者，「乾」也；山者，「艮」也。山从地而高，极其崇峻，疑若陵于天矣。然天益高远，终非山之所能陵也。君子之于小人，岂将恶而绝之哉？草木禽兽，无所不爱，而况人乎？「近之则不逊，远之则怨」，小人之常态也。「不可得而亲，不可得而疏」，君子之道也，是天山之象矣。天之所以远于山者，以其尊也；君子所以远于小人者，以其严也。恶之则怨，不严则渎。怨则召祸，渎则招侮。不恶而严，小人自远矣。故子曰：「苟志于仁矣，无恶也。人而不仁，疾之已甚，乱也。」是不恶之义也。动容貌，斯远暴慢矣；出辞气，斯远鄙倍矣，严之义也。是故君子有三变，望之俨然，即之也温，听其言也厉，其守身之道欤？杂卦曰：「遁则退也。」「遁」之为卦，以二阴浸长而成。其在六爻，以阴进阳退为义。夫阴阳之相为进退，如昼夜寒暑之常。然方其进也，一用而有余；及其退也，五存而不足。「复」、「姤」是也，而况于「临」、「遁」乎？夫「临」之世，四阴在上，而不能禁二阳之长；则「遁」之世，四阳在上，将何以御二阴之冲乎？然君子之于小人，有复育之心，而无疾恶之意，是以其卦为「临」。小人之于君子，无忠信之实，而有诈谖之情，是以其卦为「遁」也。初六有「遁尾」之厉，六二有「牛革」之坚，阴进之爻也。九三「系遁」，九四「好遁」，九五「嘉遁」，上九「肥遁」，其四阳之退乎？初六：遁尾，厉，勿用有攸往。象曰：「遁尾」之「厉」，不往何灾也？初六，「艮」也，以阴居刚，而在下卦之下，应乎九四。四，「乾」兑也，故曰「遁尾」。「兑」，西方之卦，有虎之象焉。自兑而「乾」，由西而北，「遁」之势也。易以上为首，初为尾，遁自内之外，故初六为「遁」之尾。夫六二在「遁」之世，小人居中而用事者也；初六在「遁」之世，小人在下而图进者也。小人进则君子遁矣。方遁之时，四阳外向，而初蹙其尾，迫之使遁也，故曰「厉」。又曰：「勿用有攸往。」夫猛兽之遁也，妥其尾而莫敢逐，或者从而蹙之，其首必反，不亦厉乎？为其体「艮」而居下，故戒以「勿用有攸往」而已。「大壮」之上六，「遁」之初六也；「大壮」之六五，「遁」之六二也。六二用事，故在「壮」则「丧羊」而「无悔」；初六方进，故在「壮」则触藩而「无攸利」。圣人知遁有反壮之理，故以尾为象，而戒之「勿往」。初六不往，而顺以承上，岂有羝羊触藩之祸乎？故子曰：「遁尾之厉，不往何灾也？」圣人之爱君子而惩小人至矣。六二：执之用黄牛之革，莫之胜说。象曰：执用黄牛，固志也。六二，「巽」也，以阴居柔而在下卦之中，应乎九五之「乾」，故曰：「执之用黄牛之革，莫之胜说」。「执」，读如絷。「乾」为马，「巽」为绳，故有「絷之」之象。「黄」者，中也。「牛」，顺物也。「革」，柔而坚也。九五将「遁」，六二居中而「巽」以系之，故有「黄牛之革」之象。小人用事，暗而无谋，轻而寡信，令而民莫之从，威而民莫之服，故虽得君而行政，不能以自为也，必赖君子以济其欲，求得欲从，然后惟其所为而莫敢不听矣。故六二上应九五，「巽」以从之，冀其为己留也。然君子知彼得志则吾道日消，是以翻然说而去之，「好遁」、「嘉遁」是也。小人惧君子之去，至于用其忠顺之道、柔巽之情、坚固之意，执而留之而不可得也。譬如以黄牛之革系焉，而不胜其说，君子之知几而不怀禄如此。故子曰：「执用黄牛，固志也。」言小人非能忠顺也，用其忠顺以固君子之心耳。可不察欤？九三：系遁，有疾，厉。畜臣妾，吉。象曰：「系遁」之利，有疾惫也；「畜臣妾，吉」，不可大事也。九三上体为「乾」，下体为「震」，以阳居刚而在下卦之上，上无其应，而连于六二之「巽」，故曰「系遁」。「巽」为绳，故有「系」象。震、「巽」，配也；「乾」，遇也。四阳皆「遁」，而九三最系，又比于二而系于「巽」焉，是以谓之「系遁」也，故曰「有疾厉」。疾者，害也。九三将遁，而物或害之，六二是也。君子之静也，介于石，其动也不终日。仲尼之去鲁也，不税冕而行；去齐也，接淅而行；去卫也，明日遂行。今以阳居刚而体乎乾震，见二阴之长，将欲遁而去之，有所系而不得去，危之道也。阴长而阳消，九三先及，是以在「遁」为「疾」，在「否」为包羞。故子曰：「系遁之厉，有疾惫也。」「惫也」者，言其无勇也。传曰：「执狐心之疑者，来谗贼之口；持不断之意者，开群枉之门。」九三之谓矣。故曰：「畜臣妾，吉。」夫九三于「遁」，固为有疾，若以遁为「畜臣妾」之卦，则三为「吉」。何者？以上而临下，以刚而制柔，以乾震而遇巽，则无倒持之弊矣。或曰：名卦曰「遁」，岂得以遁为「畜臣妾」之卦乎？曰：易穷则变，变则通，所以极天下之动也。「剥」之六五，岂非剥及尊位乎？乃以剥为「宠宫人」，以卦五阴而奉一阳，鱼贯而进，则六五之象无不利矣。「遁」之九三，当二阴之进，有危厉之象。若以遁为「畜臣妾」之卦，四阳而临二阴，堂阶尊严，则九三之象，斯为言矣。离之「畜牝牛吉」，亦犹是也。是以穆姜之筮，得「元亨利正」而薨；南蒯之筮，得「黄裳元吉」而败。学易者其可以不知此哉？故子曰：「畜臣妾吉，不可大事也。」上尊而下卑，可以畜臣妾而已。若当大事，而小人在内，君子在外，尊不下际，而卑不上行，其能济乎？彖之所以有「小利贞」之辞也。九四：好遁，君子吉，小人否。象曰：君子「好遁」，「小人否」也。九四上体为「乾」，下体为「兑」，以阳居柔而在上卦之下，应乎初六之「艮」，故曰「好遁」。「好」，情好也。下「艮」上「兑」，有二少相感之象焉。体乎刚健，舍之而去，是以谓之「好遁」也。故曰：「君子吉，小人否。」以「兑」则应乎「艮」，以「乾」则无应。「乾」为君子，「兑」为小人。君子见几而作，不为情好之所牵，斯为吉矣。小人唯利是视，而岂能然哉？在卦四阳为君子，而君子之中不能无小人焉，则以其体乎「兑」故也。阴欲消阳，而阳不能遁也，此其所以为「否」也。九五、六二，下「艮」上「兑」，其辞曰：「小人吉，大人否，亨。」虽若相反，其义一也。盖「好遁」者，君子之吉；而「包承」者，小人之吉也。君子之否，所以求亨；小人之否，则无自而亨矣。故子曰：「君子好遁，小人否也。」大壮九三「小人用壮，君子罔也」之义同。说者或以为「臧否」之「否」，或以为「可否」之「否」，于义亦通。但以由「遁」而「否」，当是本义。易之取义，不一而足。若「遁」者，非独见其不为情好之所牵，亦不恶而严之意也。五之「嘉遁」，亦犹是尔。九五：嘉遁，贞吉。象曰：「嘉遁，贞吉」，以正志也。九五，「乾」也。以阳居刚，而在上卦之中，应乎六二之「巽」，故曰「嘉遁」。「嘉」，配偶也。九五、六二，「乾」「巽」相应，故有「嘉偶」之象。夫情好之私，或非其正，舍之而去，犹若易然。至于伉俪之情，室家之义，幡然而改，亦已难矣，故曰「贞吉」。以此为贞，斯为吉也。何者？九五、六二，上乾下巽，有相应之形，而无相与之意也。或曰：「遁」之九五，非君位欤？曰：何为其然也？九五非君，则六二无应，不得为用事之臣矣。爻以象变，辞以爻变，岂特一端而尽之乎？故曰：「嘉遁贞吉，以正志也。」夫君子与小人，如冰炭之不侔，薰莸之不并，所以耽于情好，牵于系应，而陷溺其良心者，贪权嗜利而不能自脱故也。孟子有言：「卿为身死而不受，今为宫室之美为之；卿为身死而不受，今为妻妾之奉为之；卿为身死而不受，今为所识穷乏者得我而为之。」此之谓失其本心。然则五之「嘉遁」，君子所以正其志而已矣。彼虽欲固吾志之留，吾乃欲正吾志之遁，是以执用黄牛而莫之胜也。或曰：何谓君子与小人为好，又与之为配乎？曰：假如邪佞小人得君而用事，外之诸臣与之姻娅，则是「好」也。职相监临，位相统摄，彼有宠于中而善载于外，则是「嘉」也。能舍而遁，不亦君子之吉乎？孔子在卫，弥子之娄与子路之妻兄弟也。弥子谓子路曰：「孔子主我，卫卿可得也。」子路以告，孔子曰：「有命。」孟子为卿于齐，出吊于滕，王使盖大夫王𬴐为辅行。王𬴐朝暮见，反齐、滕之路，未尝与之言行事也。唐李鄘节度淮南，与监军吐突承璀相敬惮，由是厚善。承璀有宠于宪宗，荐之，召相鄘，鄘不喜，由承璀进，引疾固辞而罢。「好遁」、「嘉遁」，其斯人之谓欤？上九：肥遁，无不利。象曰：「肥遁，无不利」，无所疑也。上九，「乾」也。以阳居柔，下无所应，上无所与，而在一卦之外，故曰「遁」。「肥遁」，非君子之欲也。君臣猜间而道不得行；小人得志而祸将及身，故退藏以避之，可谓君子忧患之时矣。忧患之至，虽饱食而弗肥；及其无忧，虽箪瓢而匪瘠。九三之「系遁」，九四之「好遁」，九五之「嘉遁」，皆未离乎忧患之域，虽欲肥，不可得也。惟上九一爻，超然于尘垢之外，无足以累其心而疑其志者，谓之「肥遁」，不亦宜乎？故曰：「无不利。」子曰：「肥遁无不利，无所疑也。」扬子云曰：「山雌之肥。」其意得乎？释「肥遁」之义，得矣。序卦曰：遁者，退也。物不可以终遁，故受之以大壮。大壮成卦，遁之反也。自遁之壮，乾反居下，艮变为震也。乾反居下，则内健而外顺矣；艮变为震，则小往而大来矣。四阳得位而居内，二阴失势而居外，既大且壮，是以谓之「大壮」也。或曰：阴阳消长，必极其所至而后反。二阴之月，反为四阳，天道之行，未尝有是，而圣人象之，何哉？曰：然。消息盈虚者，天之行也；拨乱反正者，圣人之功也。如使存亡治乱，必极其所至而后反，则何尊乎圣人？何贵乎君子？何尚乎六经哉？是以乾至上九而受之以用九，坤至上六而受之以用六。穷则变，变则通，易之所为作也。故曰：「亢龙有悔，兴时偕极。乾元用九，乃见天则。」此圣人之志也。自遁而壮，亦犹是乎？大壮，利贞。彖曰：大壮，大者壮也。刚以动，故壮。「大壮利贞」，大者正也。正大而天地之情可见矣。下乾上震，成卦曰「大壮者，初为乾，二亦为乾，三为兑，四为震。乾，健也；震，动也。阳为大，阴为小；阳为壮，阴为羸。乾震皆阳也，斯谓之大壮矣乎？曰：物之大小，生于相形，势之强弱本于相轻。若乾与震相遇，则无余象，而谓之大壮，是乾为大而震为小矣，乾为壮而震为羸矣。为其有兑象焉，为震兑者一，为乾者二，为偶者二，为奇者四，是以谓之大壮也。故曰大壮，大者壮也，刚以动，故壮也。大壮利贞」，何谓也？曰：贞者，正也。凡易言「贞」与「征」为相反之辞。征犹往也，贞犹正也，无平不陂，无往不复。当大壮之时，四阳在内，二阴在外，此强而彼弱矣。惟君子能守其正而不迫于小人，则小人亦安其分而不谋于君子，如是足矣。苟恃其强而不思正固之道，则自壮而未可知也。故曰「大壮则止，遁则退也」。夫刚以动而系之止，为其卒乎艮故也。君子当遁之时，二阴在内，则可退而不可进；及壮之时，二阴在外，则可止不可征。夫圣人非不欲天下皆君子也，以为阴阳消长如昼夜寒暑然，穷则变矣。故三阳为泰，而戒以「无往不复」；四阳为壮，而戒以「利贞征凶」；五阳为夬，而戒以「莫夜有戎」者，畏其穷也。子曰：「大壮，利贞。」大者，正也，正大而天地之情可见矣。君子以正守其大，则其壮莫弊，其动也，孰能御之？于斯之时，福善祸淫之戒可得而窥，好生恶杀之意可得而察，裒多益寡、扶弱抑强之理可得而验，故曰：「复，其见天地之心乎？」「正大而天地之情可见矣。」老子曰：「物壮则老，是谓不道，不道早已。」夫所为食者，为饱也，饱而生疾者有之，以惩疾而废饱者，老氏之论也，然亦可以为戒矣。象曰：雷在天上，「大壮」，君子以非礼弗履。雷者，「震」也。天者，「乾」也。雷行天下，则物被其灾；雷在天上，震惊而已。是故君子以礼自防，不伤于物，所以全其壮也。恃其壮而妄行，其为遁也犹反掌耳。子路问强，子曰：「南方之强与？北方之强与？宽柔以教，不报无道，南方之强也。」君子居之，非礼弗履，斯为大壮矣。杂卦曰：「大壮则止。」大壮为卦，以四阳二阴而成。其在六爻，以各止其所为义。阳止而不迫于阴，阴止而不抗于阳，如大壮之时，则可矣。夫天下不可一日无君子也，无君子莫治小人；不可一日无小人也，无小人莫养君子。然君子常寡，而小人常众。故阳数常奇，而阴数常偶也。圣人之心，岂惟不欲小人之胜君子，亦不欲君子之胜小人。何者？天道好还，未有穷而不变者也。当「大壮」之时，虽四阳而二阴，然以其数考之，多寡适足以相当。多寡足以相当，是君子之徒半于天下也。君子之徒半于天下，是天下皆君子也。如是而止焉，君子、小人相与以治，不亦可乎？是以「大壮」诸爻，以阴居刚，以阳居柔者，皆不争而相与者也。以阴居柔，以阳居刚者，皆不相与而至于争者也。止则为吉，争则为凶。「大壮」之君子，岂不念哉？初九：壮于趾，征凶，有孚。象曰：「壮于趾」，其孚穷也。初九，「乾」也。以阳居刚，而在下卦之下，上无其应，而承于九二。二亦「乾」也，「乾」为健，故曰「壮于趾」。「壮于趾」者，其进锐也。「大壮」之君子，既得其位矣，然犹有「壮趾」之象，何也？在下而求进者也，故曰：「征凶，有孚。」初既无应于上，所以征者，其将迫九四而夺之权乎？凶之道也。然居最下之地而敢于「孚」，上人其必有所「孚」矣。初九以阳居刚，其所与者，必以阴居柔者也。在卦六爻，以阴居柔，上六而已。上六，小人之势穷者也。天下之祸常生于小人之穷，而君子之嗜进者，常出力而为之助，是以深惩而痛艾之也。诗曰：「大风有隧，贪人败类。」其是之谓乎？故曰：「壮于趾，其孚穷也。」繋辞曰：「上古穴居而野处，后世圣人易之以宫室，上栋下宇，以备风雨，盖取诸大壮。」何也？君子之所以为壮者，壮于宫室，壮于藩篱，壮于舆輹，屹然有不可动之势，则风雨鸟鼠不能入其舍，艰难险阻不能改其度，斯为壮矣。苟壮于趾，欲进而不休，岂不易穷哉？由是观圣人一字之义，其训周矣。九二：贞吉。象曰：「九二贞吉」，以中也。九二，「乾」也，以阳居柔而在下卦之中，应乎六五之「巽」，故曰「贞吉」。「贞」者，正也。「乾」「巽」之相遇，刚柔之相与，斯为正矣。九二止其健而不争，六五丧其羊而无悔，二者相济，不失乎中行，此所以为「吉」也。故曰：「九二贞吉，以中也。」九三：小人用壮，君子用罔，贞厉。羝羊触藩，羸其角。象曰：「小人用壮」，君子罔也。九三上体为「兑」，下体为「乾」，以阳居刚而在下卦之上，应乎上六之「艮」，故曰：「小人用壮，君子用罔。」「罔」，不用也。乾为君子，「兑」为小人，以「兑」则应乎「艮」，故有用壮之象；以「乾」则无应，故有不用之象。夫壮也者，君子之所以自防也。从而用之，以与物角，则丧其所以为壮者矣。然以九居三，非常能不用者也，故曰「贞厉」。羝羊触藩，羸其角。「兑」为羊。羊之为畜，其生易藩。羝则「不」字之羊也。以「兑」应「艮」，宜有相与之情，而九三、上六，阴阳偏胜，无孳乳之道，是以谓之「羝羊」也。按汉书：「匈奴使苏武牧羝，羝乳乃得归。」注曰：「羝，牡也。牡羊不能乳也。」「乳犹有配合之道，非绝其类者也。」羝是「不」字之羊，是以九三、上六皆称「羝」也。羊狠而好斗，群居则喜触。羝羊无牝牡之道，饱食无为，所以用其壮者，惟触而已。九三之羝将触，上六阂于九四而难进，故有触藩羸角之象。「大壮」之君子，苟以九三为「贞」，斯有羸角之祸矣，此其所以为「厉」也。故子曰：「小人用壮，君子罔也。」九四：贞吉，悔亡。藩决不羸，壮于大舆之輹。象曰：「藩决不羸」，尚往也。九四上体为「震」，下体为「乾」，以阳居柔，而在上卦之下，下无其应，而承于六五之「巽」，故曰：「贞吉悔亡。」四之「贞吉」，与二均耳。所以有「悔」者，不中故也。「乾」「巽」遇也，「震」「巽」配也。乾震合体以承乎「巽」。彖之所谓「刚以动故壮」是也。六五之于九四，受而不逆，故曰：「藩决不羸」。阳以四为藩，阴以五为藩。九三之来，其藩设矣。九四之来，其藩既决，则四之角不羸。故曰：「壮于大舆之輹。」輹，舆下横木也。「坤」为大舆，「震」之一画在「坤」之下，故有「舆輹」之象。輹壮则舆壮矣，舆壮则可以行矣。所以然者，九四不用其壮，故能使六五自决其藩，所谓不争而善胜者也。无触藩之羸，而有舆輹之壮焉，往而不利？故子曰：「藩决不羸，尚往也。」自四而往，其为「夬」乎？「夬」虽五阳，而一阴在上，穷则反矣。是以君子安于壮而危于「夬」也。或曰：三以体兑为羊，故有羸角之象。四，乾震也，而系之不羸，何哉？曰：此相因而成文也。三以用壮，故取羊以为之象。自四以往，虽无兑象，然皆以阴阳相触，言「大壮」之义。六五者，「兑」之反也，故为「丧羊」。三之所敌者四，是以皆称羊也。牝马龙战，亦犹是矣。六五，丧羊于易，无悔。象曰：「丧羊于易」，位不当也。上六，羝羊触藩，不能退，不能遂，无攸利，艰则吉。象曰：「不能退，不能遂」，不详也；「艰则吉」，咎不长也。六五，巽也，以阴居刚而在上卦之中；上六，艮也，以阴居柔而在上卦之上。应乎九三而止，斯为吉矣。故子曰：「不能退，不能遂，不详也；艰则吉，咎不长也。」此与临之「六三，咎不长也」之义同。九三之君子既用罔矣，而又曰贞厉；上六之小人既触藩矣，而又曰「艰则吉」，此则圣人深探物情，知艮、兑二少不能持久，故防其渐而开其自新也。使九三壮而知「厉」，上六困而知「艰」，则大壮之势，夫孰能御之哉！「详」字依郑、王本作「详」。周易经传集解卷十七。",-1)])])}const _=t(r,[["render",c]]);export{m as __pageData,_ as default};
